<?php use App\Core\Helpers as H;?><h1>Reported conversations</h1><div class="moderation-layout"><section><div class="message-inbox"><?php foreach($reports as $r):?><a class="message-row" href="/admin/message-reports/<?=$r['id']?>"><strong><?=H::e($r['shop_name'])?></strong><span><?=H::e($r['reason'])?> · <?=H::e($r['status'])?></span><small><?=H::e($r['created_at'])?></small></a><?php endforeach;?></div><?php if(!$reports):?><div class="card empty-state">No conversations have been reported.</div><?php endif;?></section><?php if($detail):?><section class="card"><h2>Report #<?=$detail['report_id']?></h2><p><?=H::e($detail['reason'])?> · <?=H::e($detail['details'])?></p><div class="thread-history"><?php foreach($messages as $m):?><article class="thread-message"><header><?=H::e($m['sender_name'])?> · <?=H::e($m['created_at'])?></header><p><?=nl2br(H::e($m['body']))?></p><?php foreach($attachments[$m['id']]??[] as $a):?><a href="/admin/message-reports/<?=$detail['report_id']?>/attachments/<?=$a['id']?>"><?=H::e($a['original_name'])?></a><?php endforeach;?></article><?php endforeach;?></div><form class="form" method="post" action="/admin/message-reports/<?=$detail['report_id']?>/moderate"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label>Status<select name="status"><?php foreach(['open','reviewing','resolved','dismissed'] as $status):?><option value="<?=H::e($status)?>" <?=$detail['status']===$status?'selected':''?>><?=H::e(ucfirst($status))?></option><?php endforeach;?></select></label><label>Moderator notes<textarea name="notes" maxlength="1000"><?=H::e($detail['moderator_notes'])?></textarea></label><button>Save moderation</button></form></section><?php endif;?></div>
